{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a neutral steroid-like cardiac glycoside, had absolute oral bioavailability of 91.2% in healthy subjects, demonstrating that steroid scaffolds can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Perindopril, a moderately lipophilic drug, had absolute oral bioavailability of 66–95% in humans, supporting high F for a lipophilic neutral compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ursodeoxycholic acid, a steroid, had systemic availability of 50% in healthy subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C65"],
      "claim": "Ethinylestradiol, a neutral steroid, had absolute bioavailability of 47.3% in healthy women, supporting moderate-to-high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "β-Methyldigoxin, a steroid glycoside, had systemic availability of 76 ± 2% in humans, another steroid with high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lefamulin, a complex lipophilic drug, had absolute oral bioavailability of 25.8% in fasted healthy adults, just above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Danazol, a steroid, had absolute oral bioavailability of 11 ± 5.2% in fasted humans, the main low-F steroid evidence; however, its low F is attributed to poor aqueous solubility, which is less applicable to the more polar query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Amphotericin B has negligible oral bioavailability, but its large polyene macrolide structure with many polar groups is not representative of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C58"],
      "claim": "Perindoprilat, the active metabolite of perindopril, had 19% bioavailability after oral prodrug administration, slightly below threshold; the query is also an active metabolite but is neutral, not a diacid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a neutral, moderately lipophilic steroid-like acetal. Most highly transferable experimental evidence from steroid and lipophilic drugs shows absolute oral bioavailability above 20% (digitoxin 91%, perindopril 66–95%, UDCA 50%, ethinylestradiol 47%, β-methyldigoxin 76%, lefamulin 26%). The main low-F evidence comes from danazol (11% fasted) and amphotericin B (negligible), but the query's higher polarity and lower MW than amphotericin and better solubility than danazol make these less applicable. Therefore, F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability data for the exact query or a corticosteroid 16,17-acetal; the closest structural class (budesonide/ciclesonide) is not represented in the evidence.",
    "Acid lability of the dioxolane ring and extent of first-pass metabolism in humans are unquantified.",
    "Food/formulation effects and transporter involvement are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

